<template>
  <div :class="['world-shell',{'comparison-mode':viewMode==='quad'}]">
    <aside class="rail"><div class="brand"><span class="brand-symbol">◎</span><div>OASIS<small>AUDIENCE WORLD</small></div></div><div class="rail-label">WORKSPACE</div><a class="rail-item active" href="/world"><span>◈</span> 人群模拟</a><router-link class="rail-item" to="/planning"><span>▤</span> 屏幕规划</router-link><router-link class="rail-item" to="/audience-demo"><span>⌘</span> 参数实验</router-link><div class="rail-label second">当前实验</div><div class="experiment"><span class="tiny-dot"></span> 城市屏幕观看行为<small>{{ run?.id ? run.id.slice(0,8).toUpperCase() : 'NEW EXPERIMENT' }}</small></div><div class="rail-note"><span>场景适配器 / v1</span><p>OASIS Agent 决策<br>合成群体 · 可追溯事件</p><div class="engine-tag">{{ run?.engine || 'OASIS' }}</div></div></aside>
    <div class="world-main">
      <header><div class="breadcrumb">模拟工作台 <span>/</span> 人群与屏幕</div><div class="header-right"><span :class="['status-dot',{running:isRunning}]"></span>{{ statusLabel }}<span class="separator"></span><router-link to="/planning">管理屏幕库存</router-link></div></header>
      <section class="titlebar"><div><h1>人群模拟</h1></div><div v-show="viewMode==='single'" class="run-buttons"><button v-if="isRunning" @click="control(run?.status==='paused'?'resume':'pause')">{{ run?.status==='paused'?'继续推演':'暂停推演' }}</button><button v-if="isRunning" @click="control('stop')">停止</button><button class="primary" :disabled="starting || isRunning || generatingLocal || localityDirty" @click="start"><span>▶</span>{{ starting ? '启动中…' : '运行 OASIS' }}</button></div></section>
      <div v-if="error" class="alert" role="alert">{{ error }}</div><div v-if="notice" class="notice" role="status">{{ notice }}</div>
      <section v-show="viewMode==='single'" class="metrics"><div><span>总人群 · 情景规模</span><b>{{ format(populationTotal) }}<small>人</small></b><p>{{ agents.length }} 个画像 · 本时段{{ cursor?'出场':'排程' }} {{ format(activePopulation) }} 人</p><i class="metric-icon">◌</i></div><div><span>加权注意人数</span><b>{{ format(noticed) }}<small>人</small></b><p><span class="mint">{{ populationTotal ? (noticed/populationTotal*100).toFixed(1) : 0 }}%</span> 占总人群 · 当前时段外推</p><i class="metric-icon">◉</i></div><div><span>加权平均停留</span><b>{{ dwell===null?'—':dwell.toFixed(1) }}<small>秒</small></b><p>按接近屏幕且反应有效的人数加权</p><i class="metric-icon">◷</i></div><div><span>推演进度</span><b>{{ run?.current_round || 0 }}<small>/ {{ world.rounds }}</small></b><p>{{ isRunning ? `本轮 ${run?.completed_decisions || 0} / ${run?.total_decisions || 0} 个 Agent 已决策` : `${run?.llm_decisions ?? run?.events.filter(e=>e.trace_id!=null).length ?? 0} 条真实 OASIS 决策` }}</p><i class="metric-icon">▥</i></div></section>
      <div v-show="viewMode==='single'" class="population-note">每个彩色节点是一个带人数权重的代表性画像，不是单个真实路人。{{ world.geographic_context ? "道路与建筑来自坐标查证地图，行程与人数仍为待校准假设。" : "街区地图与步行规则是合成情景，尚未按现场校准。" }}加权人数不会增加实际独立样本数，各轮结果不应累加为去重触达。</div>

      <div class="scene-layout-selector"><label>视图 <select aria-label="场景布局" v-model="viewMode"><option value="quad">四宫格</option><option value="single">单场景</option></select></label></div>
      <SceneComparison v-if="viewMode==='quad'" :current-run-id="run?.id" :run-complete="run?.status==='completed'" />
      <details v-show="viewMode==='single'" class="setup-disclosure"><summary>场景与人群设置</summary>
      <FrameLocationBuilder v-if="viewMode==='single'" :project-id="projectId" :disabled="isRunning || generatingLocal || starting" @apply="applyGeolocation" />
      <LocalAudienceBuilder v-show="viewMode==='single'" v-model="locality" v-model:group-count="requestedGroupCount" :venues="localVenues" :template="audienceTemplate" :dirty="localityDirty" :disabled="isRunning || generatingLocal || starting" :generating="generatingLocal" :project-id="projectId" @generate="generateLocal" />
      </details>
      <p v-if="viewMode==='single' && run && !run.scene.locality" class="legacy-note">正在回放早期通用画像。新的模拟需要先设定区域、社区与场所并生成人群。</p>
      <details v-show="viewMode==='single'" class="setup-disclosure"><summary>全天时段排程</summary><DayTimeline v-show="viewMode==='single'" :busy="starting" :schedule="world.schedule || []" :snapshots="run?.snapshots || []" :cursor="cursor" :slot="currentSlot" @select="selectHour" /></details>
      <div v-if="viewMode==='single'" class="simulation-grid">
        <section class="scene-panel"><div class="panel-head"><div><span class="mint">◈</span> 场景视图 <span class="view-chip">SCENE</span></div><div class="map-tools"><button @click="showTrails=!showTrails" :class="{selected:showTrails}">轨迹</button><button @click="selectedAgent=null; groupFilter='all'">重置视图</button></div></div>
          <div class="scene-toolbar"><span><span class="tiny-dot"></span>{{ world.scene_label }}</span><span>{{ world.geographic_context ? "地图几何 · 合成行程（未实测）" : "示意空间 · 非真实地理轨迹" }}</span></div>
          <div :class="['map-wrap',currentSlot?.period,{holiday:currentSlot?.holiday_active}]">
            <NeighborhoodMap v-if="world.neighborhood" :network="world.neighborhood" :agents="trafficFrame?.pedestrians || movementAgents" :screens="displayScreens" :vehicles="trafficFrame?.vehicles || []" :impressions="impressionCounts" :traffic-ready="!!trafficReplay" :minute="minute" :hour="String(currentSlot?.hour ?? Math.max(0,cursor-1)).padStart(2,'0')" :selected-agent="selectedAgent" :show-trails="showTrails" :group-filter="groupFilter" @agent="selectedAgent=$event;selectedScreen=null" @screen="selectedScreen=$event;selectedAgent=null" @minute="seekMinute" />
            <svg v-else class="world-map" viewBox="0 0 1000 590" role="img" aria-label="人群与户外屏幕的交互场景图">
              <defs><pattern id="world-grid" width="35" height="35" patternUnits="userSpaceOnUse"><path d="M 35 0 L 0 0 0 35" fill="none" stroke="#dce3e5" stroke-width=".6"/></pattern><pattern id="park-grid" width="14" height="14" patternUnits="userSpaceOnUse"><circle cx="7" cy="7" r="1" fill="#b8d0b7"/></pattern><filter id="screen-glow"><feGaussianBlur stdDeviation="5"/></filter></defs>
              <rect width="1000" height="590" fill="#f7f9f9"/><rect width="1000" height="590" fill="url(#world-grid)"/>
              <path d="M -30 365 L1030 365 M360 -20 L360 620 M720 -20 L720 620" stroke="#dce3e5" stroke-width="70"/>
              <path d="M -30 365 L1030 365 M360 -20 L360 620 M720 -20 L720 620" stroke="#ffffff" stroke-width="1.5" stroke-dasharray="12 14"/>
              <path d="M0 324H1000 M0 406H1000 M319 0V590 M401 0V590 M679 0V590 M761 0V590" stroke="#b2c1c6" stroke-width="2"/>
              <g fill="#ffffff" opacity=".2"><rect v-for="i in 6" :key="`cross1${i}`" :x="324+i*9" y="314" width="5" height="22"/><rect v-for="i in 6" :key="`cross2${i}`" :x="684+i*9" y="397" width="5" height="22"/></g>
              <g class="buildings"><path d="M54 57H276V151H54Z" fill="#dce4e5" stroke="#b9c9cc"/><path d="M54 57L69 43H291L276 57M276 57L291 43V137L276 151" fill="#d1dcdf" stroke="#b9c9cc"/><path d="M76 79H254M76 103H254M76 127H254" stroke="#b9c9cc"/><text x="84" y="118">OFFICE DISTRICT</text>
              <path d="M443 63H620V198H443Z" fill="#dce4e5" stroke="#b9c9cc"/><path d="M443 63L458 49H635L620 63M620 63L635 49V184L620 198" fill="#d1dcdf" stroke="#b9c9cc"/><path d="M462 87H600M462 109H600M462 132H600M462 157H600" stroke="#b9c9cc"/><text x="480" y="177">{{ world.locality ? '场所服务区域' : 'CITY MALL' }}</text>
              <path d="M805 55H936V148H805Z" fill="#dcebdc" stroke="#b4ccad"/><rect x="805" y="55" width="131" height="93" fill="url(#park-grid)"/><text x="829" y="110">CITY PARK</text>
              <path d="M70 448H270V531H70Z" fill="#dce4e5" stroke="#b9c9cc"/><path d="M70 448L82 436H282L270 448M270 448L282 436V519L270 531" fill="#d1dcdf" stroke="#b9c9cc"/><text x="111" y="498">TRANSIT HUB</text>
              <path d="M812 449H936V531H812Z" fill="#dce4e5" stroke="#b9c9cc"/><text x="839" y="496">CAFE</text></g>
              <g fill="#dcebdc" stroke="#b4ccad"><circle v-for="(tree,i) in trees" :key="i" :cx="tree[0]" :cy="tree[1]" r="10"/></g>
              <text x="432" y="355" fill="#4a5b66" font-size="10" letter-spacing="5">CENTRAL AVENUE</text><text x="26" y="560" fill="#536573" font-size="11">OASIS DECISIONS × SCENE ADAPTER</text>
              <g v-if="showTrails" class="trails"><path v-for="a in filteredAgents" :key="`trail${a.id}`" :d="trail(a.id)" fill="none" :stroke="a.color" stroke-width="1.3" stroke-dasharray="4 7" opacity=".3"/></g>
              <g v-for="s in world.screens" :key="s.id" class="screen-node" tabindex="0" role="button" :aria-label="s.name" @click="selectedScreen=s.id;selectedAgent=null" @keydown.enter="selectedScreen=s.id;selectedAgent=null">
                <ellipse :cx="s.x" :cy="s.y+10" rx="67" ry="43" fill="#49d8be" opacity=".035"/><ellipse :cx="s.x" :cy="s.y+10" rx="67" ry="43" fill="none" stroke="#5ae1bd" opacity=".25" stroke-dasharray="3 6"/>
                <rect :x="s.x-21" :y="s.y-47" width="42" height="59" rx="5" fill="#5ae1bd" opacity=".18" filter="url(#screen-glow)"/><path :d="`M${s.x} ${s.y+6}v15m-14 0h28`" stroke="#6f8f91" stroke-width="3"/><rect :x="s.x-18" :y="s.y-46" width="36" height="52" rx="4" fill="#143934" stroke="#70e2bd" stroke-width="1.5"/><rect :x="s.x-13" :y="s.y-40" width="26" height="39" rx="2" fill="#55d0ac"/><path :d="`M${s.x-7} ${s.y-26}h14m-14 6h10m-10 6h14`" stroke="#1d6553" stroke-width="2"/>
                <rect :x="s.x-76" :y="s.y+31" width="152" height="37" rx="6" fill="#ffffff" stroke="#33554e"/><text :x="s.x" :y="s.y+47" text-anchor="middle" fill="#20262b" font-size="11">{{ short(s.name,15) }}</text><text :x="s.x" :y="s.y+60" text-anchor="middle" fill="#31594e" font-size="9">{{ short(s.id,21) }}</text>
              </g>
              <g v-for="a in filteredAgents" :key="a.id" class="agent-node" :style="{transform:`translate(${a.x}px,${a.y}px)`}" tabindex="0" role="button" :aria-label="a.name" @click="selectedAgent=a.id;selectedScreen=null" @keydown.enter="selectedAgent=a.id;selectedScreen=null">
                <line v-if="a.screen_id && !['passing','unknown','away','unexposed'].includes(a.reaction) && (agents.length<=24 || selectedAgent===a.id || groupFilter!=='all')" x1="0" y1="0" :x2="screen(a.screen_id).x-a.x" :y2="screen(a.screen_id).y-a.y-20" :stroke="a.color" opacity=".45" stroke-width="1.5" stroke-dasharray="4 6" class="attention-line"/>
                <circle v-if="a.reaction==='watch'||a.reaction==='interest'" r="19" :stroke="a.color" fill="none" opacity=".28" class="watch-ring"/><circle v-if="selectedAgent===a.id" r="17" stroke="white" stroke-width="1" fill="none"/>
                <circle r="10" :fill="a.color" opacity=".18"/><circle r="5.8" :fill="a.color" stroke="#e5fff8" stroke-width="1.2"/><path v-if="a.reaction==='passing'" d="M-14 0h-9m11 5h-7" :stroke="a.color" stroke-width="1.2" opacity=".5"/>
                <g v-if="selectedAgent===a.id"><rect x="-51" y="-40" width="102" height="23" rx="4" fill="#edf6f2"/><text y="-24" text-anchor="middle" fill="#13352e" font-size="11">{{ a.name }}</text></g>
              </g>
            </svg>
            <div v-if="!world.neighborhood" class="map-overlay"><span class="tiny-dot"></span>{{ run?.status==='running' ? 'AGENTS THINKING' : run?.status==='completed' ? 'OASIS TRACE REPLAY' : 'SCENE READY' }}<b>{{ isDaily ? `${currentSlot?.time} · ${currentSlot?.period_label}` : `ROUND ${cursor.toString().padStart(2,'0')}` }}</b><small v-if="isDaily">{{ cursor ? '记录回放' : '排程预览' }} · {{ activeAgents.length }} 个代表出场</small></div>
          </div>
          <div class="agent-locator"><label>定位代表性画像<select v-model="selectedAgent" @change="selectedScreen=null;groupFilter='all'"><option :value="null">选择 Agent，查看画像与代表人数</option><option v-for="a in agents" :key="a.id" :value="a.id">{{ a.name }} · {{ format(weight(a)) }} 人</option></select></label><span>实际模拟 {{ agents.length }} 个 Agent，权重合计 {{ format(populationTotal) }} 人</span></div><div class="legend"><button :class="{selected:groupFilter==='all'}" @click="groupFilter='all'">全部群体</button><button v-for="g in world.groups" :key="g.id" :class="{selected:groupFilter===g.id}" @click="groupFilter=groupFilter===g.id?'all':g.id"><i :style="{background:g.color}"></i>{{ g.name }}</button><span class="legend-hint">点击 Agent 查看决策原因</span></div>
          <div class="timeline"><button :aria-label="playing?'暂停回放':'播放回放'" class="playback" :disabled="maxRound===0" @click="togglePlayback">{{ playing?'Ⅱ':'▶' }}</button><span class="round-text">{{ isDaily ? `${currentSlot?.time || '00:00'} · ${cursor}/${world.rounds} 小时` : `${cursor}/${maxRound} 轮` }}</span><input type="range" min="0" :max="maxRound" :value="cursor" :disabled="maxRound===0" @input="seek" aria-label="模拟轮次回放"><select v-model.number="speed" aria-label="回放速度"><option v-for="v in [.25,.5,1,2,4,8,16,32]" :key="v" :value="v">{{ v }}×</option></select><label><input v-model="loopPlayback" type="checkbox">循环播放</label><label><input v-model="followLive" type="checkbox" @change="followLatest">跟随最新</label></div>
        </section>
        <aside class="inspector"><details class="config-panel"><summary class="panel-head">实验设置</summary><div class="config-inputs"><label>代表性 Agent<input v-model.number="population" type="number" min="4" max="200" :disabled="isRunning"></label><label>总人群规模<input v-model.number="totalPopulation" type="number" :min="population" max="1000000" step="1000" :disabled="isRunning"></label></div><div class="traffic-controls"><b>车辆与更多行人</b><label>每个代表展开行人 <select aria-label="每个代表展开行人" v-model.number="trafficOptions.pedestrians_per_agent"><option v-for="n in [1,2,4,6,8,10]" :key="n" :value="n">{{ n }} 个</option></select></label><label>车辆 / 基准小时 <input aria-label="每小时基准车辆" type="number" min="0" max="3000" step="100" v-model.number="trafficOptions.vehicles_per_hour"></label><button @click="loadTraffic" :disabled="loadingTraffic||(!run&&localityDirty)">{{ loadingTraffic?'正在生成行人与车辆…':'应用人车设置' }}</button><small>最多 {{ population*trafficOptions.pedestrians_per_agent }} 个步行样本，分摊原人群权重，不新增 LLM 独立样本。车辆随高峰与节日变化。</small></div><div class="mobility-controls"><b>周边出行情景</b><label>全程步行抽样概率 <input aria-label="全程步行抽样概率" type="number" min="0" max="1" step="0.05" v-model.number="mobility.walking_share" :disabled="isRunning"> </label><label>顺路浏览抽样概率 <input aria-label="顺路浏览抽样概率" type="number" min="0" max="1" step="0.05" v-model.number="mobility.explore_share" :disabled="isRunning"></label><small>0–1 的情景假设，非当地统计。普通穿行画像保持步行。修改后预览或重新运行生效。</small></div><DayCycleControls v-if="dayCycle" v-model="dayCycle" :presets="holidayPresets" :disabled="isRunning" /><label class="source-check"><input v-model="useInventory" type="checkbox" :disabled="isRunning || !projectId">使用最近规划库存（最多 3 块）</label><div class="cohort-actions"><button :disabled="isRunning" @click="showCohorts=true">编辑 {{ segments.length }} 类人群画像</button><button :disabled="isRunning || starting || localityDirty || generatingLocal" @click="previewPopulation">预览代表人群</button></div><p>每天 24 轮，{{ dayCycle?.days || 1 }} 天最多 {{ population*24*(dayCycle?.days || 1) }} 次 LLM 请求；只对当时段出场的代表调用。循环回放不产生新请求。修改后请预览或开始新推演。</p></details>
          <section v-if="person" class="person-panel"><div class="panel-head">Agent 观察窗<button @click="selectedAgent=null">×</button></div><div class="person-heading"><span :style="{background:person.color}">{{ person.name.slice(0,1) }}</span><div><b>{{ person.name }}</b><small>AGENT {{ String(person.id).padStart(3,'0') }} · 代表 {{ format(weight(person)) }} 人</small></div></div><span :class="['reaction-tag',person.reaction]">{{ reactions[person.reaction] }}</span><p class="reason">“{{ person.reason }}”</p><dl><dt>当前屏幕</dt><dd>{{ person.screen_id||'尚未相遇' }}</dd><dt>观看时长</dt><dd>{{ person.dwell_seconds == null ? '未观测' : person.dwell_seconds+' 秒' }}</dd></dl><dl v-if="person.journey" class="journey-fields"><dt>出行方式</dt><dd>{{ person.journey.mode_label }}</dd><dt>出行目的</dt><dd>{{ person.journey.purpose }}</dd><dt>起点 → 终点</dt><dd>{{ person.journey.origin }} → {{ person.journey.destination }}</dd><dt>顺路停留</dt><dd>{{ person.journey.stops.join('、') || '直接穿行' }}</dd><dt>离开方式</dt><dd>{{ person.journey.departure_mode==='walking'?'步行离开':'接续公共交通' }}</dd><dt>空间来源</dt><dd>合成路线；未使用真实轨迹</dd></dl><dl v-if="person.encounter" class="encounter-fields"><dt>本轮路线</dt><dd>{{ person.encounter.route }}</dd><dt>视线条件</dt><dd>{{ person.encounter.line_of_sight ? '有观看机会' : '背向或遮挡' }}</dd><dt>机会窗口</dt><dd>{{ person.encounter.available_seconds }} 秒（假设）</dd><dt>当下任务</dt><dd>{{ person.encounter.current_task }}</dd></dl><div v-if="person.local_context" class="local-person"><h4>地区与社区关联 · 模型推演</h4><dl><template v-for="(label,key) in localLabels" :key="key"><dt>{{ label }}</dt><dd>{{ person.local_context[key] }}</dd></template></dl><p>{{ person.local_rationale }}</p><small>引用：{{ person.source_ids.join('、') }}</small></div><dl v-if="person.audience_profile" class="profile-fields"><template v-for="(label,key) in profileLabels" :key="key"><dt>{{ label }}</dt><dd>{{ person.audience_profile[key] || '未提供' }}</dd></template></dl><p v-else>{{ person.persona }}</p><p>画像来源：{{ person.profile_source || '早期合成场景' }}<br>人数权重：{{ (weight(person)/Math.max(1,populationTotal)*100).toFixed(2) }}%</p><p v-if="trafficReplay" class="expanded-person-note">这里显示原代表的 OASIS 记录；展开行人的独立路线见地图，不额外生成观看决策。</p><div class="provenance">{{ cursor>0 ? person.reaction==='away'?'来源：时间场景排程，未调用 LLM':person.reaction==='unexposed'?'来源：街区路线，未调用 LLM':'来源：OASIS INTERVIEW 记录' : '来源：初始合成人设' }}</div></section>
          <section v-else-if="selectedScreen" class="person-panel"><div class="panel-head">屏幕观察窗<button @click="selectedScreen=null">×</button></div><h3>{{ screen(selectedScreen).name }}</h3><p>{{ screen(selectedScreen).venue }}</p><dl><dt>累计曝光机会</dt><dd>{{ format(impressionCounts[selectedScreen]?.total || 0) }} 次</dd><dt>行人 / 车内人数</dt><dd>{{ format(impressionCounts[selectedScreen]?.pedestrian || 0) }} / {{ format(impressionCounts[selectedScreen]?.vehicle || 0) }}</dd><dt>可见性输入</dt><dd>{{ screen(selectedScreen).visibility == null ? '未知（无现场证据）' : Math.round(screen(selectedScreen).visibility*100)+'%' }}</dd><dt>本轮注意</dt><dd>{{ format(agents.filter(a=>a.screen_id===selectedScreen&&!['passing','unknown','away','unexposed'].includes(a.reaction)).reduce((n,a)=>n+weight(a),0)) }} 人（加权）</dd></dl><p>{{ screen(selectedScreen).source || "这是场景输入与合成 Agent 行为，不是实测广告效果。" }}</p></section>
          <details class="events-panel"><summary class="panel-head">行为记录 · {{ visibleEvents.length }}</summary><div class="event-list"><div v-if="!visibleEvents.length" class="empty-events"><span>◌</span><p>{{ cursor ? '本时段无可显示的模型决策' : '点击「运行 OASIS」' }}<br>{{ cursor ? '未出场由时间场景排程记录' : '观察 Agent 的模型决策与步行记录' }}</p></div><button v-for="(e,i) in visibleEvents.slice(0,30)" :key="`${e.round}-${e.agent_id}`" class="event" @click="selectedAgent=e.agent_id;selectedScreen=null"><i :style="{background:e.color}"></i><div><div class="event-title"><b>{{ e.name }}</b><small>{{ e.time || `R${e.round}` }}</small></div><p><span :class="e.reaction">{{ reactions[e.reaction] }}</span> · 代表 {{ format(e.represented_population || 1) }} 人 · {{ short(e.screen_id,16) }}</p><small>{{ e.reason }}</small></div></button></div></details>
        </aside>
      </div>
      <section v-show="viewMode==='single'" class="bottom-grid"><div class="group-panel"><div class="panel-head">加权群体反应分布<span class="muted">注意人数 / 总人数 · 加权</span></div><div class="group-rows"><div v-for="g in world.groups" :key="g.id" class="group-row"><span><i :style="{background:g.color}"></i>{{ g.name }}</span><div class="segments"><span v-for="(label,key) in reactions" :key="key" :class="key" :style="{width:groupPercent(g.id,key)+'%'}" :title="label+' '+format(groupCount(g.id,key))+' 人（加权）'"></span></div><small>{{ format(groupCount(g.id,'glance')+groupCount(g.id,'watch')+groupCount(g.id,'interest')) }} / {{ format(groupPopulation(g.id)) }}</small></div></div><div class="reaction-legend"><span v-for="(label,key) in reactions" :key="key"><i :class="key"></i>{{ label }}</span></div></div><div class="run-panel"><div class="panel-head">运行记录<button :disabled="!run" @click="download">导出 JSON</button></div><p>{{ run?.message || '准备开始一个新的多 Agent 场景实验。' }}</p><div class="run-details"><span>决策引擎<b>{{ run?.engine || 'OASIS' }}</b></span><span>语言模型<b>{{ run?.model || '配置的 DeepSeek' }}</b></span><span>空间模型<b>{{ world.neighborhood ? "街区步行网络" : "示意场景适配层" }}</b></span></div><p class="footnote">人数权重只用于情景外推；同一代表画像不等于其代表的所有人都必然做出相同行为。消费能力与家庭背景来自配置，不从照片或真实个人身份推断。暂停 / 停止在当前轮次结束后生效。</p></div></section>
    </div>
    <div v-if="showCohorts" class="cohort-modal" @click.self="showCohorts=false">
      <section class="cohort-dialog" role="dialog" aria-modal="true" aria-label="人群画像与占比配置">
        <div class="panel-head">人群画像与占比配置<button @click="showCohorts=false">关闭</button></div>
        <p class="cohort-intro">占比自动归一化为设定的总人群；每类非空人群至少分配一个代表性 Agent。所有内置画像均为合成假设，请用地区资料或消费者调研校正。编辑不会改变已有运行记录。本地画像的活动系数、社区关系与资料引用同样保留。</p>
        <div class="cohort-editor"><nav><button v-for="(g,i) in segments" :key="g.id" :class="{selected:i===segmentIndex}" @click="segmentIndex=i"><b>{{ g.name }}</b><small>相对占比 {{ g.share }}</small></button><button :disabled="segments.length>=40" @click="addSegment">＋ 添加人群</button></nav>
          <div v-if="editingSegment" class="cohort-form"><div class="cohort-form-grid"><label>人群名称<input v-model="editingSegment.name" maxlength="100"></label><label>相对占比<input v-model.number="editingSegment.share" type="number" min="0" max="1000000" step="1"></label><label v-for="(label,key) in editableProfileLabels" :key="key">{{ label }}<textarea v-model="editingSegment.profile[key]" rows="2" maxlength="1000" /></label></div><details v-if="editingSegment.local_context" class="local-cohort-fields"><summary>社区、场所与活动时段参数</summary><label v-for="(label,key) in localLabels" :key="key">{{ label }}<textarea v-model="editingSegment.local_context[key]" rows="2" maxlength="1000" /></label><label>本地化依据<textarea v-model="editingSegment.local_rationale" rows="3" maxlength="2000" /></label><div class="cohort-form-grid"><label v-for="(label,key) in activityLabels" :key="key">{{ label }}<input v-model.number="editingSegment.activity_factors[key]" type="number" min="0" max="2" step="0.1"></label></div><p>引用：{{ editingSegment.source_ids.join('、') }} · 相对人数与时段系数为情景参数</p></details><label>来源 / 假设依据<textarea v-model="editingSegment.source" rows="2" maxlength="1000" /></label><button :disabled="segments.length<=1" @click="removeSegment">移除此类人群</button></div></div>
        <div class="cohort-footer"><span>{{ segments.length }} 类 · 相对占比之和 {{ segments.reduce((n,g)=>n+(Number(g.share)||0),0) }}（无需恰好 100）</span><button class="primary" @click="showCohorts=false;previewPopulation()">应用并预览人群</button></div>
      </section>
    </div>
  </div>
</template>
<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import SceneComparison from '../components/SceneComparison.vue'
import NeighborhoodMap from '../components/NeighborhoodMap.vue'
import DayCycleControls from '../components/DayCycleControls.vue'
import FrameLocationBuilder from '../components/FrameLocationBuilder.vue'
import LocalAudienceBuilder from '../components/LocalAudienceBuilder.vue'
import DayTimeline from '../components/DayTimeline.vue'
import {indexImpressions,impressionsAt} from '../utils/trafficPlayback'
import {advancePlayback} from '../utils/worldPlayback'
import api from '../api'
const world=ref({agents:[],screens:[],groups:[],rounds:4,scene_label:'城市商业街 · 概念场景'})
const run=ref(null),error=ref(''),notice=ref(''),starting=ref(false),population=ref(100),totalPopulation=ref(10000),rounds=ref(4),useInventory=ref(false),projectId=ref(null)
const cursor=ref(0),selectedAgent=ref(null),selectedScreen=ref(null),groupFilter=ref('all'),showTrails=ref(false),followLive=ref(true),playing=ref(false),speed=ref(1)
const locality=ref({country:'',city:'',community:'',venue_type:'',venue_name:'',languages:'',cultural_notes:'',community_notes:'',sources:[]}),audienceTemplate=ref(null),generatedLocality=ref(''),localVenues=ref([]),requestedGroupCount=ref(12),generatingLocal=ref(false)
const localityDirty=computed(()=>!audienceTemplate.value || JSON.stringify(locality.value)!==generatedLocality.value)
const localLabels={community_relation:'社区关系',visit_purpose:'到访目的',language_context:'语言环境',cultural_context:'文化关联与边界',community_context:'社区生活与联系',venue_behavior:'场所观看机会'}
const activityLabels={morning:'早间活动系数',evening:'下班活动系数',night:'夜间活动系数',daytime:'日间活动系数',quiet:'深夜活动系数'}
const trafficOptions=ref({pedestrians_per_agent:4,vehicles_per_hour:1200}),trafficReplay=ref(null),loadingTraffic=ref(false)
let trafficTicket=0
const mobility=ref({walking_share:.75,explore_share:.4}),minute=ref(30)
const dayCycle=ref(null),holidayPresets=ref([]),loopPlayback=ref(true),previewHour=ref(0)
const reactions={away:'本时段未出场',unexposed:'周边活动 / 未接近屏幕',passing:'路过 / 未注意',glance:'短暂注视',watch:'停留观看',interest:'产生兴趣',unknown:'未知 / 未观测'}
const segments=ref([]),showCohorts=ref(false),segmentIndex=ref(0),previewMode=ref(false)
const editableProfileLabels={life_stage:'生活阶段',purchasing_power:'消费能力',economic_context:'经济背景 / 阶层情景',household:'家庭情况',preferences:'消费倾向',needs:'消费需求',price_sensitivity:'价格敏感度',mobility:'移动方式',attention_context:'注意力情景'}
const profileLabels={...editableProfileLabels,time_pressure:'当下时间压力',attention_habit:'注意习惯',purchase_planning:'购买计划',current_need:'当前需求',decision_style:'决策习惯',purchase_channel:'购物渠道'}
const editingSegment=computed(()=>segments.value[segmentIndex.value])
const weight=a=>a.represented_population ?? 1
const format=n=>Number(n).toLocaleString('zh-CN',{maximumFractionDigits:0})
const populationTotal=computed(()=>agents.value.reduce((n,a)=>n+weight(a),0))
const trees=[[50,222],[82,224],[110,223],[456,250],[485,253],[608,258],[825,182],[858,184],[891,184],[924,184],[455,512],[492,516],[530,514],[567,516],[606,514]]
const agents=computed(()=>run.value?.snapshots[cursor.value]?.agents||world.value.agents)
const movementAgents=computed(()=>cursor.value?agents.value:agents.value.map(a=>({...a,journey:world.value.mobility_rounds?.[previewHour.value]?.[String(a.id)]})))
const trafficFrame=computed(()=>trafficReplay.value?.frames[(cursor.value||previewHour.value+1)-1])
const displayScreens=computed(()=>trafficReplay.value?.screens||world.value.screens)
const impressionIndex=computed(()=>indexImpressions(trafficReplay.value?.events))
const impressionCounts=computed(()=>impressionsAt(impressionIndex.value,cursor.value||previewHour.value+1,minute.value))
const currentSlot=computed(()=>run.value?.snapshots[cursor.value]?.slot || world.value.schedule?.[previewHour.value] || null)
const isDaily=computed(()=>!!world.value.schedule?.length)
const activeAgents=computed(()=>cursor.value?agents.value.filter(a=>a.reaction!=='away'):isDaily.value?agents.value.filter(a=>currentSlot.value?.present_agent_ids.includes(a.id)):agents.value)
const activePopulation=computed(()=>activeAgents.value.reduce((n,a)=>n+weight(a),0))
const filteredAgents=computed(()=>activeAgents.value.filter(a=>groupFilter.value==='all'||a.group===groupFilter.value))
const maxRound=computed(()=>Math.max(0,(run.value?.snapshots.length||1)-1))
const person=computed(()=>agents.value.find(a=>a.id===selectedAgent.value))
const noticed=computed(()=>cursor.value?agents.value.filter(a=>!['passing','unknown','away','unexposed'].includes(a.reaction)).reduce((n,a)=>n+weight(a),0):0)
const dwell=computed(()=>{if(!cursor.value)return null;const known=agents.value.filter(a=>!['unknown','away','unexposed'].includes(a.reaction));const total=known.reduce((n,a)=>n+weight(a),0);return total?known.reduce((n,a)=>n+(a.dwell_seconds||0)*weight(a),0)/total:null})
const visibleEvents=computed(()=>(run.value?.events||[]).filter(e=>e.reaction!=='away' && (isDaily.value?e.round===cursor.value:e.round<=cursor.value)&&(groupFilter.value==='all'||e.group===groupFilter.value)).slice().reverse())
const isRunning=computed(()=>['queued','initializing','running','paused'].includes(run.value?.status))
const statusLabel=computed(()=>({queued:'等待启动',initializing:'初始化引擎',running:'正在推演',paused:'已暂停',completed:'推演完成',failed:'运行失败',stopped:'已停止'}[run.value?.status]||'场景就绪'))
const short=(v,n)=>String(v||'').length>n?String(v).slice(0,n)+'…':v
const screen=id=>displayScreens.value.find(s=>s.id===id)||{x:0,y:0}
const groupCount=(id,reaction)=>agents.value.filter(a=>a.group===id&&(cursor.value?a.reaction:'unknown')===reaction).reduce((n,a)=>n+weight(a),0)
const groupPopulation=id=>agents.value.filter(a=>a.group===id).reduce((n,a)=>n+weight(a),0)
const groupPercent=(id,reaction)=>100*groupCount(id,reaction)/Math.max(1,groupPopulation(id))
function addSegment(){const g=JSON.parse(JSON.stringify(segments.value[0]));g.id=`custom-${Date.now()}`;g.name='自定义人群';g.share=5;g.source='用户设定的情景假设';segments.value.push(g);segmentIndex.value=segments.value.length-1}
function removeSegment(){segments.value.splice(segmentIndex.value,1);segmentIndex.value=Math.max(0,segmentIndex.value-1)}
const requestedLayout=new URLSearchParams(window.location.search).get('layout')
const viewMode=ref(requestedLayout==='quad'?'quad':requestedLayout==='single'?'single':localStorage.getItem('pdooh-scene-layout')==='single'?'single':'quad')
watch(viewMode,async value=>{localStorage.setItem('pdooh-scene-layout',value);if(value==='quad')playing.value=false;else if(run.value?.id){try{apply((await api.get(`/api/world/runs/${run.value.id}`)).data);if(!trafficReplay.value&&!loadingTraffic.value)loadTraffic()}catch(e){error.value=e.message}}})
function config(){return {agent_count:population.value,total_population:totalPopulation.value,seed:42,segments:segments.value,day_cycle:dayCycle.value,locality:locality.value,template_id:audienceTemplate.value?.id,mobility:mobility.value,traffic_options:trafficOptions.value}}
async function applyGeolocation(result){locality.value=JSON.parse(JSON.stringify(result.locality));audienceTemplate.value=null;generatedLocality.value='';notice.value='已应用坐标查证地点，正在生成该地点的人群模板。';await generateLocal()}
function acceptTemplate(value){audienceTemplate.value=value;locality.value=JSON.parse(JSON.stringify(value.locality));generatedLocality.value=JSON.stringify(locality.value);segments.value=JSON.parse(JSON.stringify(value.segments));requestedGroupCount.value=value.segments.length}
async function generateLocal(){error.value='';if(requestedGroupCount.value>population.value){error.value='细分群体数不能超过代表性 Agent 数';return}generatingLocal.value=true;playing.value=false;try{const r=await api.post('/api/world/local-audiences',{locality:locality.value,group_count:requestedGroupCount.value});acceptTemplate(r.data);localStorage.setItem('pdooh-local-audience-template',JSON.stringify(r.data));await previewPopulation()}catch(e){error.value=e.message}finally{generatingLocal.value=false}}
async function previewPopulation(){if(localityDirty.value){error.value='请先按当前国家、社区、场所和资料重新生成本地画像';return}error.value='';starting.value=true;playing.value=false;try{const r=await api.post('/api/world/preview',config());world.value=r.data;run.value=null;trafficReplay.value=null;cursor.value=0;previewHour.value=0;selectedAgent.value=null;groupFilter.value='all';previewMode.value=true;await loadTraffic();notice.value=`已生成 ${world.value.agents.length} 个代表画像，权重合计 ${format(world.value.total_population)} 人。尚未调用模型。`}catch(e){error.value=e.message}finally{starting.value=false}}
async function loadTraffic(){const ticket=++trafficTicket;loadingTraffic.value=true;try{const r=run.value?await api.post(`/api/world/runs/${run.value.id}/traffic`,{traffic_options:trafficOptions.value}):await api.post('/api/world/traffic-preview',config());if(ticket===trafficTicket){trafficReplay.value=r.data;error.value=''}}catch(e){if(ticket===trafficTicket)error.value=e.message}finally{if(ticket===trafficTicket)loadingTraffic.value=false}}
function trail(id){return (run.value?.snapshots||[]).slice(0,cursor.value+1).map((s,i)=>`${i?'L':'M'}${s.agents[id].x},${s.agents[id].y}`).join(' ')}
function apply(value){const changed=run.value?.id!==value.id;if(value.scene.mobility)mobility.value={...value.scene.mobility};const newlyComplete=value.status==='completed' && (run.value?.id!==value.id || run.value?.status!=='completed');if(run.value?.id!==value.id){trafficReplay.value=null;error.value='';selectedAgent.value=null;cursor.value=0}run.value=value;world.value=value.scene;if(followLive.value)cursor.value=value.snapshots.length-1;if(newlyComplete&&value.scene.schedule?.length&&loopPlayback.value){cursor.value=value.scene.neighborhood?(value.scene.schedule.find(s=>s.period==='morning')?.round||1):1;followLive.value=false;playing.value=viewMode.value==='single';lastTick=Date.now();if(value.scene.neighborhood)minute.value=30}if(value.status==='failed')error.value=value.message;else error.value='';if(changed||newlyComplete){if(value.scene.traffic_options)trafficOptions.value={...value.scene.traffic_options};if(viewMode.value==='single')loadTraffic()}}
async function start(){starting.value=true;error.value='';notice.value='';playing.value=false;try{const data=config();if(useInventory.value)data.project_id=projectId.value;const r=await api.post('/api/world/runs',data);previewMode.value=false;followLive.value=true;previewHour.value=0;cursor.value=0;selectedAgent.value=null;apply(r.data)}catch(e){error.value=e.message}finally{starting.value=false}}
async function poll(){if(previewMode.value||(viewMode.value==='quad'&&!isRunning.value))return;try{if(viewMode.value==='quad'&&run.value){const id=run.value.id;const r=await api.get(`/api/world/runs/${id}/summary`);if(run.value?.id===id)run.value={...run.value,...r.data};return}if(!run.value||!isRunning.value){const r=await (new URLSearchParams(window.location.search).has('project')?Promise.resolve({data:null}):api.get('/api/world/latest'));if(r.data&&r.data.id!==run.value?.id)apply(r.data);return}const id=run.value.id;const r=await api.get(`/api/world/runs/${id}`);if(run.value?.id===id)apply(r.data)}catch(e){error.value=e.message}}
async function control(command){try{await api.post(`/api/world/runs/${run.value.id}/control`,{command});notice.value=command==='resume'?'正在继续推演。':'控制请求已发送，在当前轮次完成后生效。'}catch(e){error.value=e.message}}
function followLatest(){if(followLive.value){playing.value=false;cursor.value=maxRound.value}}
function seekMinute(value){playing.value=false;followLive.value=false;minute.value=value}
watch(cursor,()=>{minute.value=playing.value?0:30},{flush:'sync'})
function seek(e){playing.value=false;followLive.value=false;cursor.value=Number(e.target.value)}
function togglePlayback(){followLive.value=false;if(!playing.value&&cursor.value>=maxRound.value&&(!world.value.neighborhood||minute.value>=59.99))cursor.value=isDaily.value?1:0;playing.value=!playing.value;lastTick=Date.now()}
function selectHour(slot){playing.value=false;followLive.value=false;if(run.value?.snapshots.some(s=>s.round===slot.round)){cursor.value=slot.round;notice.value=''}else if(!run.value){previewHour.value=slot.round-1}else{notice.value=`${slot.date} ${slot.time} 尚未生成决策记录。`}}
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify({...run.value,traffic_replay:trafficReplay.value},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`oasis-world-${run.value.id.slice(0,8)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
let polling,timer,lastTick=0
onMounted(async()=>{try{projectId.value=new URLSearchParams(window.location.search).get('project')||localStorage.getItem('pdooh-planning-project');const [s,r,g,d,l]=await Promise.all([api.get('/api/world/scene'),(new URLSearchParams(window.location.search).has('project')?Promise.resolve({data:null}):api.get('/api/world/latest')),api.get('/api/world/segments'),api.get('/api/world/day-presets'),api.get('/api/world/locality-options')]);localVenues.value=l.data.venues;world.value=s.data;segments.value=g.data;dayCycle.value=d.data.default;holidayPresets.value=d.data.holidays;if(r.data?.scene.schema_version>=2){population.value=r.data.scene.agents.length;totalPopulation.value=r.data.scene.total_population;segments.value=JSON.parse(JSON.stringify(r.data.scene.groups));if(r.data.scene.locality){audienceTemplate.value=r.data.scene.audience_template;locality.value=JSON.parse(JSON.stringify(r.data.scene.locality));generatedLocality.value=JSON.stringify(locality.value);requestedGroupCount.value=segments.value.length;}if(r.data.scene.day_cycle){dayCycle.value=JSON.parse(JSON.stringify(r.data.scene.day_cycle));apply(r.data)}else if(['running','queued','initializing','paused'].includes(r.data.status)){apply(r.data)}else{apply(r.data)}}else{previewMode.value=true}let draft=null;try{draft=JSON.parse((new URLSearchParams(window.location.search).has('project')?sessionStorage.getItem('pdooh-project-template-'+projectId.value):localStorage.getItem('pdooh-local-audience-template'))||'null')}catch{}if(draft?.id&&!isRunning.value&&(!audienceTemplate.value||draft.generated_at>audienceTemplate.value.generated_at)){acceptTemplate(draft);await previewPopulation()}}catch(e){error.value=e.message}polling=setInterval(poll,2500);timer=setInterval(()=>{if(!playing.value)return;if(world.value.neighborhood){const now=Date.now();minute.value+=(now-lastTick)*60*speed.value/(trafficReplay.value?30000:12000);lastTick=now;if(minute.value<60)return;minute.value=0}else{if(Date.now()-lastTick<1800/speed.value)return;lastTick=Date.now()}const next=advancePlayback({cursor:cursor.value,maxRound:maxRound.value,complete:!isRunning.value,loop:loopPlayback.value,firstFrame:isDaily.value?1:0});cursor.value=next.cursor;playing.value=next.playing;if(!next.playing)minute.value=59.99},50)})
onUnmounted(()=>{trafficTicket++;clearInterval(polling);clearInterval(timer)})
</script>
